<template><a-form><a-input v-model:value="form.name"/><div v-for="(panel,index) in form.panels" :key="index"><a-input v-model:value="panel.title"/><a-select v-model:value="panel.panel_type" :options="typeOptions"/><a-select v-model:value="panel.unit" :options="unitOptions"/><a-select v-model:value="panel.width" :options="widthOptions"/><a-button @click="move(index,-1)">Up</a-button><a-button @click="move(index,1)">Down</a-button></div><a-button @click="addPanel">Add panel</a-button></a-form></template>
<script setup lang="ts">
import{computed,reactive}from'vue';import type{NamedRef,PanelInput,SaveDashboard}from'@/types/observability';defineProps<{datasources:NamedRef[]}>();const form=reactive<SaveDashboard>({name:'',description:'',refresh_interval_s:30,time_range:'1h',panels:[]});const typeOptions=['time_series','stat','table'].map(value=>({value,label:value}));const unitOptions=['','percent','bytes','cores','seconds','rate'].map(value=>({value,label:value||'none'}));const widthOptions=[6,12].map(value=>({value,label:String(value)}));function addPanel(){const panel:PanelInput={datasource_id:0,title:'Panel',panel_type:'time_series',promql:'',unit:'',legend:'',sort_order:form.panels.length,width:12};form.panels.push(panel)}function move(index:number,delta:number){const target=index+delta;if(target<0||target>=form.panels.length)return;const item=form.panels.splice(index,1)[0];if(item)form.panels.splice(target,0,item);form.panels.forEach((p,i)=>p.sort_order=i)}const valid=computed(()=>!!form.name.trim()&&form.panels.length>0&&form.panels.every(p=>!!p.title.trim()&&['time_series','stat','table'].includes(p.panel_type)&&[6,12].includes(p.width)));defineExpose({form,addPanel,move,valid})
</script>
